def help_text(prog):
    lines = [
        f"{prog}: {DESC}",
        "",
        "Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.",
        "Specify file paths to edit as a command argument or run without argument to",
        "start to write a new text.",
        "Help can show up with key mapping Ctrl-?.",
        "",
        "Usage:",
        f"    {prog} [options] [FILES...]",
        "",
        "Mappings:",
    ]
    for k,v in HELP_MAPPINGS:
        lines.append(f"    {k:<30}: {v}")
    lines += [
        "",
        "Options:",
        "    -v, --version       Print version",
        "    -h, --help          Print this help",
        "",
    ]
    return "\n".join(lines)

def parse_args(argv):
    # Behaviour resembles the observed getopts parser. --h/--v are accepted aliases.
    files=[]; help_seen=False; ver_seen=False
    endopts=False
    for arg in argv[1:]:
        if endopts:
            files.append(arg); continue
        if arg == "--":
            endopts=True; continue
        if arg.startswith("--") and len(arg)>2:
            name = arg[2:]
            val = None
            if "=" in name:
                name,val = name.split("=",1)
            if name in ("help","h"):
                if val is not None:
                    return ("err", f"Option 'help' does not take an argument. Please see --help for more details")
                if help_seen:
                    return ("err", "Option 'help' given more than once. Please see --help for more details")
                help_seen=True
            elif name in ("version","v"):
                if val is not None:
                    return ("err", f"Option 'version' does not take an argument. Please see --help for more details")
                if ver_seen:
                    return ("err", "Option 'version' given more than once. Please see --help for more details")
                ver_seen=True
            else:
                # observed --foo=bar reports just foo
                return ("err", f"Unrecognized option: '{name}'. Please see --help for more details")
        elif arg.startswith("-") and arg != "-":
            for ch in arg[1:]:
                if ch == 'h':
                    if help_seen:
                        return ("err", "Option 'help' given more than once. Please see --help for more details")
                    help_seen=True
                elif ch == 'v':
                    if ver_seen:
                        return ("err", "Option 'version' given more than once. Please see --help for more details")
                    ver_seen=True
                else:
                    return ("err", f"Unrecognized option: '{ch}'. Please see --help for more details")
        else:
            files.append(arg)
    if ver_seen: return ("version", files)
    if help_seen: return ("help", files)
    return ("run", files)

def char_width(ch):
    if ch == '\t': return 0
    o=ord(ch)
    if o == 0: return 0
    if unicodedata.combining(ch): return 0
    if unicodedata.category(ch) in ('Cc','Cf'):
        return 0
    if unicodedata.east_asian_width(ch) in ('F','W'):
        return 2
    return 1

def str_display_width(s):
    x=0
    for ch in s:
        if ch == '\t':
            x += 8 - (x % 8)
        else:
            x += char_width(ch)
    return x

def render_line(s, start_col, width):
    # Expand tabs and crop by display columns.
    pieces=[]; x=0
    for ch in s:
        if ch == '\t':
            n=8-(x%8); text=' '*n; w=n
        else:
            text=ch; w=max(1,char_width(ch))
        for c in text:
            if x >= start_col and len(''.join(pieces)) < width:
                pieces.append(c)
            x += 1
            if len(''.join(pieces)) >= width: break
        if len(''.join(pieces)) >= width: break
    return ''.join(pieces)

def render_pos(s, idx):
    x=0
    for ch in s[:idx]:
        if ch == '\t': x += 8-(x%8)
        else: x += max(1,char_width(ch))
    return x

def index_from_render_pos(s, rx):
    x=0
    for i,ch in enumerate(s):
        w = 8-(x%8) if ch=='\t' else max(1,char_width(ch))
        if x + w > rx: return i
        x += w
    return len(s)

def validate_text(text):
    for ch in text:
        if ch in ('\n','\t'): continue
        o=ord(ch)
        # Reject ASCII controls. DEL is treated as invalid too.
        if o < 32 or o == 127:
            if o < 16:
                rep = f"\\u{{{o:x}}}"
            else:
                rep = f"\\u{{{o:x}}}"
            raise ValueError(f"Invalid character for text is included: '{rep}'")

def load_file(path):
    with open(path,'rb') as f:
        data=f.read()
    try:
        text=data.decode('utf-8')
    except UnicodeDecodeError:
        raise UnicodeError("stream did not contain valid UTF-8")
    validate_text(text)
    if text == '': return []
    lines=text.split('\n')
    if lines and lines[-1] == '': lines.pop()
    return lines

