                if seq.startswith(b'[') and len(seq)>=2 and (64 <= seq[-1] <= 126) and seq[-1:] != b'[':
                    if seq[-1:] != b'~' or len(seq)>=3: break
                elif not seq.startswith(b'[') and not seq.startswith(b'O'):
                    break
            if seq==b'': return ('esc',None)
            if seq in (b'[A',): return 'up'
            if seq in (b'[B',): return 'down'
            if seq in (b'[C',): return 'right'
            if seq in (b'[D',): return 'left'
            if seq in (b'[H',b'OH'): return 'home'
            if seq in (b'[F',b'OF'): return 'end'
            if seq in (b'[3~',): return 'delete'
            if seq in (b'[5~',): return 'pgup'
            if seq in (b'[6~',): return 'pgdn'
            if seq in (b'[1~',b'[7~'): return 'home'
            if seq in (b'[4~',b'[8~'): return 'end'
            if seq in (b'[1;5C',b'[5C'): return ('ctrl','right')
            if seq in (b'[1;5D',b'[5D'): return ('ctrl','left')
            if seq in (b'[1;5A',b'[5A'): return ('ctrl','up')
            if seq in (b'[1;5B',b'[5B'): return ('ctrl','down')
            if len(seq)==1:
                ch=seq.decode('latin1')
                return ('alt',ch)
            return ('alt',seq.decode('latin1','replace'))
        if c==0x7f: return 'backspace'
        if c==0x0d or c==0x0a: return 'enter'
        if 0 < c < 32:
            return ('ctrl', chr(c+96))
        if c < 128:
            return chr(c)
