        name=self.prompt("Open: ", " (Empty name for new text buffer, ^G or ESC to cancel)")
        if name is None:
            self.set_message("Canceled"); return
        if name=='':
            nb=Buffer(None,[])
        else:
            try: lines=load_file(name); nb=Buffer(name,lines)
            except FileNotFoundError: nb=Buffer(name,[],missing=True)
            except Exception as e:
                self.set_message(str(e), True); return
