            if k in ('enter',):
                self.set_message('')
                return buf
            if k in (('ctrl','g'), ('esc',None)):
                return None
            if k in ('backspace', ('ctrl','h')):
                buf=buf[:-1]
            elif isinstance(k,str) and len(k)==1 and ord(k)>=32:
                buf += k
            elif isinstance(k,tuple) and k[0]=='alt':
                # ESC during prompt cancels only if alone; alt ignored
                pass
            # redraw underlying if needed only for search prompt outside
    def switch_next(self):
        if self.buffers:
            self.current=(self.current+1)%len(self.buffers); self.set_message('')
    def switch_prev(self):
        if self.buffers:
            self.current=(self.current-1)%len(self.buffers); self.set_message('')
