        elif k in ('down',('ctrl','n')): b.move('down',self.screenrows)
        elif k in ('right',('ctrl','f')): b.move('right',self.screenrows)
        elif k in ('left',('ctrl','b')): b.move('left',self.screenrows)
        elif k in ('home',('ctrl','a'),('alt','[D')): b.move('home',self.screenrows)
        elif k in ('end',('ctrl','e'),('alt','[C')): b.move('end',self.screenrows)
        elif k in ('pgdn',('ctrl','['),('ctrl','v')): b.move('pgdn',self.screenrows)
        elif k in ('pgup',('ctrl',']'),('alt','v')): b.move('pgup',self.screenrows)
