        elif k in (('alt','b'),('ctrl','left')): b.move_word_back()
        elif k in (('alt','n'),('ctrl','down')): b.move_para_next()
        elif k in (('alt','p'),('ctrl','up')): b.move_para_prev()
        elif k==('alt','<'): b.move_top()
        elif k==('alt','>'): b.move_bottom()
        elif k in ('backspace',('ctrl','h')): b.del_back()
        elif k in ('delete',('ctrl','d')): b.del_forward()
        elif k==('ctrl','w'): b.delete_word()
        elif k==('ctrl','j'): b.delete_to_bol()
        elif k==('ctrl','k'): b.delete_to_eol()
        elif k==('ctrl','u'):
            if not b.undo_change(): self.set_message("Already at oldest change")
        elif k==('ctrl','r'):
            if not b.redo_change(): self.set_message("Already at newest change")
        elif k==('ctrl','g'):
            self.search()
        elif k==('ctrl','m') or k=='enter':
            b.insert_newline()
