        else:
            self.error_key(k)
    def run(self):
        self.enter_alt()
        self.enable_raw()
        try:
            self.refresh()
            while self.running:
                k=self.read_key()
                self.handle_key(k)
                if self.running:
                    self.search_query=None; self.search_current=None
                    self.refresh()
        finally:
            self.disable_raw()
            self.exit_alt()

def main():
    status=parse_args(sys.argv)
    if status[0]=='err':
        print('Error: '+status[1], file=sys.stderr)
        return 1
    if status[0]=='version':
        print(VERSION); return 0
    if status[0]=='help':
        sys.stdout.write(help_text(sys.argv[0])); return 0
    try:
        try:
            ed=Editor(status[1])
        except OSError as e:
            # Match Rust-ish display for ioctl failure.
            if getattr(e,'errno',None)==errno.ENOTTY:
                print("Error: Inappropriate ioctl for device (os error 25)", file=sys.stderr)
            else:
                print(f"Error: {e}", file=sys.stderr)
            return 1
        try:
            ed.run(); return 0
        except RuntimeError as e:
            # Some file load errors occur after entering alt screen in the original; this path is rarely used.
            print('Error: '+str(e), file=sys.stderr); return 1
    except RuntimeError as e:
        print('Error: '+str(e), file=sys.stderr); return 1

if __name__=='__main__':
    sys.exit(main())
