#!/usr/bin/env python3
import sys, os, termios, tty, fcntl, struct, select, unicodedata, copy, errno

VERSION = "0.4.3"
DESC = "A tiny UTF-8 terminal text editor"
HELP_MAPPINGS = [
("Ctrl-Q", "Quit"),
("Ctrl-S", "Save to file"),
("Ctrl-O", "Open text buffer"),
("Ctrl-X", "Next text buffer"),
("Alt-X", "Previous text buffer"),
("Ctrl-P or UP", "Move cursor up"),
("Ctrl-N or DOWN", "Move cursor down"),
("Ctrl-F or RIGHT", "Move cursor right"),
("Ctrl-B or LEFT", "Move cursor left"),
("Ctrl-A or Alt-LEFT or HOME", "Move cursor to head of line"),
("Ctrl-E or Alt-RIGHT or END", "Move cursor to end of line"),
("Ctrl-[ or Ctrl-V or PAGE DOWN", "Next page"),
("Ctrl-] or Alt-V or PAGE UP", "Previous page"),
("Alt-F or Ctrl-RIGHT", "Move cursor to next word"),
("Alt-B or Ctrl-LEFT", "Move cursor to previous word"),
("Alt-N or Ctrl-DOWN", "Move cursor to next paragraph"),
("Alt-P or Ctrl-UP", "Move cursor to previous paragraph"),
("Alt-<", "Move cursor to top of file"),
("Alt->", "Move cursor to bottom of file"),
("Ctrl-H or BACKSPACE", "Delete character"),
("Ctrl-D or DELETE", "Delete next character"),
("Ctrl-W", "Delete a word"),
("Ctrl-J", "Delete until head of line"),
("Ctrl-K", "Delete until end of line"),
("Ctrl-U", "Undo last change"),
("Ctrl-R", "Redo last undo change"),
("Ctrl-G", "Search text"),
("Ctrl-M", "New line"),
("Ctrl-L", "Refresh screen"),
("Ctrl-?", "Show this help"),
]

def help_text(prog):
    lines = [
        f"{prog}: {DESC}",
        "",
        "Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.",
        "Specify file paths to edit as a command argument or run without argument to",
        "start to write a new text.",
        "Help can show up with key mapping Ctrl-?.",
        "",
        "Usage:",
        f"    {prog} [options] [FILES...]",
        "",
        "Mappings:",
    ]
    for k,v in HELP_MAPPINGS:
        lines.append(f"    {k:<30}: {v}")
    lines += [
        "",
        "Options:",
        "    -v, --version       Print version",
        "    -h, --help          Print this help",
        "",
    ]
    return "\n".join(lines)

def parse_args(argv):
    # Behaviour resembles the observed getopts parser. --h/--v are accepted aliases.
    files=[]; help_seen=False; ver_seen=False
    endopts=False
    for arg in argv[1:]:
        if endopts:
            files.append(arg); continue
        if arg == "--":
            endopts=True; continue
        if arg.startswith("--") and len(arg)>2:
            name = arg[2:]
            val = None
            if "=" in name:
                name,val = name.split("=",1)
            if name in ("help","h"):
                if val is not None:
                    return ("err", f"Option 'help' does not take an argument. Please see --help for more details")
                if help_seen:
                    return ("err", "Option 'help' given more than once. Please see --help for more details")
                help_seen=True
            elif name in ("version","v"):
                if val is not None:
                    return ("err", f"Option 'version' does not take an argument. Please see --help for more details")
                if ver_seen:
                    return ("err", "Option 'version' given more than once. Please see --help for more details")
                ver_seen=True
            else:
                # observed --foo=bar reports just foo
                return ("err", f"Unrecognized option: '{name}'. Please see --help for more details")
        elif arg.startswith("-") and arg != "-":
            for ch in arg[1:]:
                if ch == 'h':
                    if help_seen:
                        return ("err", "Option 'help' given more than once. Please see --help for more details")
                    help_seen=True
                elif ch == 'v':
                    if ver_seen:
                        return ("err", "Option 'version' given more than once. Please see --help for more details")
                    ver_seen=True
                else:
                    return ("err", f"Unrecognized option: '{ch}'. Please see --help for more details")
        else:
            files.append(arg)
    if ver_seen: return ("version", files)
    if help_seen: return ("help", files)
    return ("run", files)

def char_width(ch):
    if ch == '\t': return 0
    o=ord(ch)
    if o == 0: return 0
    if unicodedata.combining(ch): return 0
    if unicodedata.category(ch) in ('Cc','Cf'):
        return 0
    if unicodedata.east_asian_width(ch) in ('F','W'):
        return 2
    return 1

def str_display_width(s):
    x=0
    for ch in s:
        if ch == '\t':
            x += 8 - (x % 8)
        else:
            x += char_width(ch)
    return x

def render_line(s, start_col, width):
    # Expand tabs and crop by display columns.
    pieces=[]; x=0
    for ch in s:
        if ch == '\t':
            n=8-(x%8); text=' '*n; w=n
        else:
            text=ch; w=max(1,char_width(ch))
        for c in text:
            if x >= start_col and len(''.join(pieces)) < width:
                pieces.append(c)
            x += 1
            if len(''.join(pieces)) >= width: break
        if len(''.join(pieces)) >= width: break
    return ''.join(pieces)

def render_pos(s, idx):
    x=0
    for ch in s[:idx]:
        if ch == '\t': x += 8-(x%8)
        else: x += max(1,char_width(ch))
    return x

def index_from_render_pos(s, rx):
    x=0
    for i,ch in enumerate(s):
        w = 8-(x%8) if ch=='\t' else max(1,char_width(ch))
        if x + w > rx: return i
        x += w
    return len(s)

def validate_text(text):
    for ch in text:
        if ch in ('\n','\t'): continue
        o=ord(ch)
        # Reject ASCII controls. DEL is treated as invalid too.
        if o < 32 or o == 127:
            if o < 16:
                rep = f"\\u{{{o:x}}}"
            else:
                rep = f"\\u{{{o:x}}}"
            raise ValueError(f"Invalid character for text is included: '{rep}'")

def load_file(path):
    with open(path,'rb') as f:
        data=f.read()
    try:
        text=data.decode('utf-8')
    except UnicodeDecodeError:
        raise UnicodeError("stream did not contain valid UTF-8")
    validate_text(text)
    if text == '': return []
    lines=text.split('\n')
    if lines and lines[-1] == '': lines.pop()
    return lines

class Buffer:
    def __init__(self, filename=None, lines=None, missing=False):
        self.filename=filename
        self.lines = [] if lines is None else list(lines)
        if missing and not self.lines:
            self.lines=['']
        self.cx=0; self.cy=0; self.rowoff=0; self.coloff=0; self.preferred_rx=None
        self.dirty=False
        self.undo=[]; self.redo=[]
        self.syntax='plain'
    def display_name(self):
        return self.filename if self.filename else "[No Name]"
    def line_count_for_status(self):
        if len(self.lines)==0 and self.filename is None: return 1
        return len(self.lines)
    def ensure_line(self):
        if not self.lines:
            self.lines.append('')
            self.cy=0; self.cx=0
    def snapshot(self):
        return (list(self.lines), self.cx, self.cy)
    def restore(self,snap):
        self.lines,self.cx,self.cy = list(snap[0]), snap[1], snap[2]
        self.clamp_cursor()
    def record(self):
        self.undo.append(self.snapshot())
        if len(self.undo)>1000: self.undo.pop(0)
        self.redo.clear()
    def changed(self):
        self.dirty=True
    def clamp_cursor(self):
        if not self.lines:
            self.cy=0; self.cx=0; return
        self.cy=max(0,min(self.cy,len(self.lines)-1))
        self.cx=max(0,min(self.cx,len(self.lines[self.cy])))
    def insert_char(self,ch):
        if ch=='\r': ch='\n'
        if ch=='\n': return self.insert_newline()
        self.record(); self.ensure_line()
        line=self.lines[self.cy]
        self.lines[self.cy]=line[:self.cx]+ch+line[self.cx:]
        self.cx += 1; self.changed()
    def insert_newline(self):
        self.record(); self.ensure_line()
        line=self.lines[self.cy]
        self.lines[self.cy]=line[:self.cx]
        self.lines.insert(self.cy+1,line[self.cx:])
        self.cy += 1; self.cx=0; self.changed()
    def del_back(self):
        if not self.lines: return
        if self.cx==0 and self.cy==0: return
        self.record()
        if self.cx>0:
            line=self.lines[self.cy]
            self.lines[self.cy]=line[:self.cx-1]+line[self.cx:]
            self.cx-=1
        else:
            prevlen=len(self.lines[self.cy-1])
            self.lines[self.cy-1]+=self.lines[self.cy]
            del self.lines[self.cy]
            self.cy-=1; self.cx=prevlen
        self.changed()
    def del_forward(self):
        if not self.lines: return
        if self.cy>=len(self.lines): return
        line=self.lines[self.cy]
        if self.cx>=len(line):
            if self.cy+1>=len(self.lines): return
            self.record(); self.lines[self.cy]+=self.lines[self.cy+1]; del self.lines[self.cy+1]
        else:
            self.record(); self.lines[self.cy]=line[:self.cx]+line[self.cx+1:]
        self.changed()
    def delete_word(self):
        if not self.lines: return
        self.recorded=False
        def rec():
            if not self.recorded:
                self.record(); self.recorded=True
        while self.cy>0 or self.cx>0:
            if self.cx==0:
                rec(); prevlen=len(self.lines[self.cy-1]); self.lines[self.cy-1]+=self.lines[self.cy]; del self.lines[self.cy]; self.cy-=1; self.cx=prevlen; break
            line=self.lines[self.cy]
            ch=line[self.cx-1]
            if not ch.isspace(): break
            rec(); self.lines[self.cy]=line[:self.cx-1]+line[self.cx:]; self.cx-=1
        while self.cy>0 or self.cx>0:
            if self.cx==0: break
            line=self.lines[self.cy]
            ch=line[self.cx-1]
            if ch.isspace(): break
            rec(); self.lines[self.cy]=line[:self.cx-1]+line[self.cx:]; self.cx-=1
        if self.recorded: self.changed()
    def delete_to_bol(self):
        if not self.lines or self.cx==0: return
        self.record(); line=self.lines[self.cy]
        self.lines[self.cy]=line[self.cx:]; self.cx=0; self.changed()
    def delete_to_eol(self):
        if not self.lines: return
        line=self.lines[self.cy]
        if self.cx < len(line):
            self.record(); self.lines[self.cy]=line[:self.cx]; self.changed()
        elif self.cy+1 < len(self.lines):
            self.record(); self.lines[self.cy]+=self.lines[self.cy+1]; del self.lines[self.cy+1]; self.changed()
    def undo_change(self):
        if not self.undo: return False
        self.redo.append(self.snapshot())
        self.restore(self.undo.pop())
        self.dirty=True
        return True
    def redo_change(self):
        if not self.redo: return False
        self.undo.append(self.snapshot())
        self.restore(self.redo.pop())
        self.dirty=True
        return True
    def move(self, key, screenrows=1):
        if key=='left':
            if self.cx>0: self.cx-=1
            elif self.cy>0: self.cy-=1; self.cx=len(self.lines[self.cy]) if self.lines else 0
        elif key=='right':
            if self.lines and self.cy < len(self.lines):
                if self.cx < len(self.lines[self.cy]): self.cx+=1
                elif self.cy+1 < len(self.lines): self.cy+=1; self.cx=0
        elif key=='up':
            if self.cy>0: self.cy-=1
        elif key=='down':
            if self.lines and self.cy+1 < len(self.lines): self.cy+=1
        elif key=='home': self.cx=0
        elif key=='end': self.cx=len(self.lines[self.cy]) if self.lines and self.cy<len(self.lines) else 0
        elif key=='pgdn':
            self.cy = min(max(0,len(self.lines)-1), self.cy + screenrows) if self.lines else 0
        elif key=='pgup':
            self.cy = max(0, self.cy - screenrows)
        self.clamp_cursor()
    def move_top(self): self.cy=0; self.cx=0
    def move_bottom(self):
        if self.lines:
            self.cy=len(self.lines)-1; self.cx=len(self.lines[self.cy])
        else: self.cy=0; self.cx=0
    def move_word_forward(self):
        if not self.lines: return
        y,x=self.cy,self.cx
        while y < len(self.lines):
            line=self.lines[y]
            while x < len(line) and not line[x].isalnum(): x+=1
            while x < len(line) and line[x].isalnum(): x+=1
            if x < len(line): break
            if y+1 >= len(self.lines): break
            y+=1; x=0
            if self.lines[y]: break
        self.cy,self.cx=y,x; self.clamp_cursor()
    def move_word_back(self):
        if not self.lines: return
        y,x=self.cy,self.cx
        if x==0 and y>0: y-=1; x=len(self.lines[y])
        while y>=0:
            line=self.lines[y]
            while x>0 and not line[x-1].isalnum(): x-=1
            while x>0 and line[x-1].isalnum(): x-=1
            if x>0 or y==0: break
            y-=1; x=len(self.lines[y])
        self.cy,self.cx=y,x; self.clamp_cursor()
    def move_para_next(self):
        if not self.lines: return
        y=self.cy+1
        while y < len(self.lines) and self.lines[y].strip(): y+=1
        while y < len(self.lines) and not self.lines[y].strip(): y+=1
        self.cy=min(y,len(self.lines)-1); self.cx=0
    def move_para_prev(self):
        if not self.lines: return
        y=self.cy-1
        while y>0 and not self.lines[y].strip(): y-=1
        while y>0 and self.lines[y-1].strip(): y-=1
        self.cy=max(0,y); self.cx=0

class Editor:
    def __init__(self, files):
        self.rows, self.cols = self.get_size()
        self.screenrows=max(1,self.rows-2)
        self.buffers=[]; self.current=0
        self.message="Ctrl-? for help"; self.message_error=False
        self.running=True; self.raw_saved=None
        self.search_query=None; self.search_current=None; self.search_matches=[]
        if files:
            for p in files:
                self.open_path_initial(p)
        else:
            self.buffers=[Buffer(None, [])]
    def get_size(self):
        try:
            s=struct.unpack('HHHH', fcntl.ioctl(sys.stdout.fileno(), termios.TIOCGWINSZ, struct.pack('HHHH',0,0,0,0)))
            rows,cols=s[0],s[1]
            if rows<=0 or cols<=0: raise OSError(errno.ENOTTY, 'Inappropriate ioctl for device')
            return rows,cols
        except OSError as e:
            raise
    def open_path_initial(self,p):
        try:
            lines=load_file(p)
            self.buffers.append(Buffer(p,lines))
        except FileNotFoundError:
            self.buffers.append(Buffer(p,[],missing=True))
        except UnicodeError as e:
            raise RuntimeError(str(e))
        except ValueError as e:
            raise RuntimeError(str(e))
    @property
    def buf(self): return self.buffers[self.current]
    def write(self,s): os.write(sys.stdout.fileno(), s.encode('utf-8','replace'))
    def enter_alt(self): self.write('\x1b[?1049h')
    def exit_alt(self): self.write('\x1b[?1049l\x1b[H')
    def enable_raw(self):
        try:
            self.raw_saved=termios.tcgetattr(sys.stdin.fileno())
            tty.setraw(sys.stdin.fileno())
        except termios.error:
            self.raw_saved=None
    def disable_raw(self):
        if self.raw_saved is not None:
            try: termios.tcsetattr(sys.stdin.fileno(), termios.TCSAFLUSH, self.raw_saved)
            except termios.error: pass
            self.raw_saved=None
    def refresh_size(self):
        try:
            self.rows,self.cols=self.get_size(); self.screenrows=max(1,self.rows-2)
        except Exception: pass
    def scroll(self):
        b=self.buf
        b.clamp_cursor()
        rx=render_pos(b.lines[b.cy], b.cx) if b.lines and b.cy<len(b.lines) else 0
        if b.cy < b.rowoff: b.rowoff=b.cy
        if b.cy >= b.rowoff + self.screenrows: b.rowoff=b.cy-self.screenrows+1
        if rx < b.coloff: b.coloff=rx
        if rx >= b.coloff + self.cols: b.coloff=rx-self.cols+1
    def row_text_with_highlight(self, line):
        if not self.search_query:
            return render_line(line, self.buf.coloff, self.cols)
        # Simple full-line render with visible search colors before cropping; adequate for common tests.
        q=self.search_query
        out=''; i=0; n=len(q)
        while i < len(line):
            if q and line.startswith(q,i):
                # current match highlighted white; others yellow
                iscur = self.search_current and self.search_current[0] == self.rendering_file_y and self.search_current[1] == i
                out += ('\x1b[107m\x1b[30m' if iscur else '\x1b[103m\x1b[30m') + line[i:i+n] + '\x1b[39;0m\x1b[39;0m'
                i += n
            else:
                out += line[i]; i += 1
        # no horizontal crop with escape awareness; return prefix including escapes
        return out[:max(self.cols*8,self.cols)]
    def draw_rows(self):
        b=self.buf
        for y in range(self.screenrows):
            filerow=y+b.rowoff
            self.write(f"\x1b[{y+1}H")
            if filerow < len(b.lines):
                self.write("\x1b[39;0m")
                self.rendering_file_y=filerow
                if self.search_query:
                    text=self.row_text_with_highlight(b.lines[filerow])
                else:
                    text=render_line(b.lines[filerow], b.coloff, self.cols)
                self.write(text)
                self.write("\x1b[39;0m\x1b[K")
            else:
                self.write("\x1b[37m~")
                if len(b.lines)==0 and b.filename is None and y == self.screenrows//3:
                    welcome=f"Kiro editor -- version {VERSION}"
                    if len(welcome)>self.cols: welcome=welcome[:self.cols]
                    padding=max(0,(self.cols-len(welcome))//2)
                    if padding:
                        self.write("\x1b[39;0m" + " "*padding + welcome)
                    else:
                        self.write("\x1b[39;0m" + welcome)
                else:
                    self.write("\x1b[39;0m")
                self.write("\x1b[K")
    def draw_status(self):
        b=self.buf
        left=f'"{b.display_name()}" - {self.current+1}/{len(self.buffers)}'
        if b.dirty: left += " (modified)"
        total=b.line_count_for_status()
        right=f"{b.syntax} {b.cy+1}/{total}"
        if len(left)+len(right) < self.cols:
            status=left + ' '*(self.cols-len(left)-len(right)) + right
        else:
            status=left[:self.cols]
        if len(status)<self.cols: status += ' '*(self.cols-len(status))
        self.write(f"\x1b[{self.rows-1}H\x1b[7m" + status[:self.cols] + "\x1b[39;0m")
    def draw_message(self):
        self.write(f"\x1b[{self.rows}H")
        msg=self.message or ''
        if self.message_error:
            self.write("\x1b[97m\x1b[41m" + msg[:self.cols] + "\x1b[39;0m\x1b[K")
        else:
            self.write(msg[:self.cols] + "\x1b[K")
    def refresh(self, status=True, message=True, show_cursor=True):
        self.refresh_size(); self.screenrows=max(1,self.rows-2); self.scroll()
        self.write("\x1b[?25l\x1b[39;0m")
        self.draw_rows()
        self.write("\x1b[39;0m")
        if status: self.draw_status()
        if message: self.draw_message()
        b=self.buf
        rx=render_pos(b.lines[b.cy], b.cx) if b.lines and b.cy < len(b.lines) else 0
        cx=max(0,rx-b.coloff)+1; cy=max(0,b.cy-b.rowoff)+1
        if cx<1: cx=1
        if cy<1: cy=1
        self.write(f"\x1b[{cy};{cx}H" if not (cy==1 and cx==1) else "\x1b[H")
        if show_cursor: self.write("\x1b[?25h")
    def set_message(self,msg,err=False):
        self.message=msg; self.message_error=err
    def key_name(self,k):
        if isinstance(k,tuple):
            typ,val=k
            if typ=='alt': return 'M-'+val
            if typ=='ctrl': return 'C-'+val
            return str(val)
        return str(k)
    def error_key(self,k):
        self.set_message(f"Key '{self.key_name(k)}' not mapped", True)
    def read_byte(self, timeout=None):
        r,_,_=select.select([sys.stdin.fileno()],[],[],timeout)
        if not r: return None
        b=os.read(sys.stdin.fileno(),1)
        return b if b else None
    def read_key(self):
        b=self.read_byte(None)
        if b is None: return None
        c=b[0]
        if c==0x1b:
            # collect escape sequence briefly
            seq=b''
            while True:
                nb=self.read_byte(0.01)
                if nb is None: break
                seq+=nb
                if len(seq)>=6: break
                # common final byte
                if seq.startswith(b'[') and len(seq)>=2 and (64 <= seq[-1] <= 126) and seq[-1:] != b'[':
                    if seq[-1:] != b'~' or len(seq)>=3: break
                elif not seq.startswith(b'[') and not seq.startswith(b'O'):
                    break
            if seq==b'': return ('esc',None)
            if seq in (b'[A',): return 'up'
            if seq in (b'[B',): return 'down'
            if seq in (b'[C',): return 'right'
            if seq in (b'[D',): return 'left'
            if seq in (b'[H',b'OH'): return 'home'
            if seq in (b'[F',b'OF'): return 'end'
            if seq in (b'[3~',): return 'delete'
            if seq in (b'[5~',): return 'pgup'
            if seq in (b'[6~',): return 'pgdn'
            if seq in (b'[1~',b'[7~'): return 'home'
            if seq in (b'[4~',b'[8~'): return 'end'
            if seq in (b'[1;5C',b'[5C'): return ('ctrl','right')
            if seq in (b'[1;5D',b'[5D'): return ('ctrl','left')
            if seq in (b'[1;5A',b'[5A'): return ('ctrl','up')
            if seq in (b'[1;5B',b'[5B'): return ('ctrl','down')
            if len(seq)==1:
                ch=seq.decode('latin1')
                return ('alt',ch)
            return ('alt',seq.decode('latin1','replace'))
        if c==0x7f: return 'backspace'
        if c==0x0d or c==0x0a: return 'enter'
        if 0 < c < 32:
            return ('ctrl', chr(c+96))
        if c < 128:
            return chr(c)
        # UTF-8 char
        data=bytes([c])
        while True:
            try:
                return data.decode('utf-8')
            except UnicodeDecodeError as e:
                if len(data)>=4: return None
                nb=self.read_byte(0.02)
                if nb is None: return None
                data+=nb
    def save_current(self):
        b=self.buf
        if not b.filename:
            name=self.prompt("Save as: ", " (^G or ESC to cancel)")
            if name is None:
                self.set_message("Canceled")
                return
            if name == '':
                self.set_message("Canceled")
                return
            b.filename=name
        data='\n'.join(b.lines) + '\n'
        try:
            with open(b.filename,'w',encoding='utf-8',newline='') as f: f.write(data)
            b.dirty=False
            self.set_message(f"{len(data.encode('utf-8'))} bytes written to {b.filename}")
        except Exception as e:
            self.set_message(f"Could not save: {e}", True)
    def open_prompt(self):
        name=self.prompt("Open: ", " (Empty name for new text buffer, ^G or ESC to cancel)")
        if name is None:
            self.set_message("Canceled"); return
        if name=='':
            nb=Buffer(None,[])
        else:
            try: lines=load_file(name); nb=Buffer(name,lines)
            except FileNotFoundError: nb=Buffer(name,[],missing=True)
            except Exception as e:
                self.set_message(str(e), True); return
        self.buffers.append(nb); self.current=len(self.buffers)-1
        self.set_message("")
    def prompt(self, prefix, suffix):
        buf=''
        while True:
            self.write(f"\x1b[?25l\x1b[{self.rows}H")
            msg=(prefix+buf+suffix)[:self.cols]
            self.write(msg + "\x1b[K")
            # editor cursor first like observed, then prompt cursor
            b=self.buf; rx=render_pos(b.lines[b.cy], b.cx) if b.lines and b.cy<len(b.lines) else 0
            cy=max(0,b.cy-b.rowoff)+1; cx=max(0,rx-b.coloff)+1
            self.write(f"\x1b[{cy};{cx}H\x1b[?25h")
            pc=min(self.cols, len(prefix)+str_display_width(buf)+1)
            self.write(f"\x1b[{self.rows};{pc}H")
            k=self.read_key()
            if k in ('enter',):
                self.set_message('')
                return buf
            if k in (('ctrl','g'), ('esc',None)):
                return None
            if k in ('backspace', ('ctrl','h')):
                buf=buf[:-1]
            elif isinstance(k,str) and len(k)==1 and ord(k)>=32:
                buf += k
            elif isinstance(k,tuple) and k[0]=='alt':
                # ESC during prompt cancels only if alone; alt ignored
                pass
            # redraw underlying if needed only for search prompt outside
    def switch_next(self):
        if self.buffers:
            self.current=(self.current+1)%len(self.buffers); self.set_message('')
    def switch_prev(self):
        if self.buffers:
            self.current=(self.current-1)%len(self.buffers); self.set_message('')
    def find_matches(self,q):
        m=[]
        if not q: return m
        for y,line in enumerate(self.buf.lines):
            start=0
            while True:
                i=line.find(q,start)
                if i<0: break
                m.append((y,i)); start=i+max(1,len(q))
        return m
    def search(self):
        old=(self.buf.cx,self.buf.cy,self.buf.rowoff,self.buf.coloff)
        q=''; cur_idx=0
        while True:
            self.search_query=q if q else None
            self.search_matches=self.find_matches(q)
            if self.search_matches:
                cur_idx%=len(self.search_matches)
                self.search_current=self.search_matches[cur_idx]
                self.buf.cy,self.buf.cx=self.search_current[0],self.search_current[1]
            else:
                self.search_current=None
            self.refresh(status=True,message=False)
            suffix=" (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to backward, ^G or ESC to cancel)"
            self.write(f"\x1b[?25l\x1b[{self.rows}H" + ("Search: "+q+suffix)[:self.cols] + "\x1b[K")
            self.write(f"\x1b[{self.rows};{min(self.cols,9+str_display_width(q))}H\x1b[?25h")
            k=self.read_key()
            if k=='enter':
                self.search_query=None; self.search_current=None
                self.set_message("Found" if q and self.search_matches else "Not found")
                return
            if k in (('ctrl','g'), ('esc',None)):
                self.buf.cx,self.buf.cy,self.buf.rowoff,self.buf.coloff=old
                self.search_query=None; self.search_current=None
                self.set_message("Canceled")
                return
            if k in ('backspace', ('ctrl','h')):
                q=q[:-1]; cur_idx=0
            elif k in ('right','down',('ctrl','f'),('ctrl','n')):
                if self.search_matches: cur_idx=(cur_idx+1)%len(self.search_matches)
            elif k in ('left','up',('ctrl','b'),('ctrl','p')):
                if self.search_matches: cur_idx=(cur_idx-1)%len(self.search_matches)
            elif isinstance(k,str) and len(k)==1 and ord(k)>=32:
                q+=k; cur_idx=0
    def show_help(self):
        # Draw visible help lines over the edit area. Next key returns to editor.
        self.write("\x1b[?25h")
        for i,(k,v) in enumerate(HELP_MAPPINGS[:self.screenrows]):
            self.write(f"\x1b[{i+1}H\x1b[96m{k:<30}\x1b[39;0m: {v}"[:self.cols+30] + "\x1b[K")
        self.read_key()
    def handle_key(self,k):
        b=self.buf
        if k==('ctrl','q'):
            if any(buf.dirty for buf in self.buffers):
                self.set_message("At least one file has unsaved changes! Press Ctrl-Q again to quit", True)
                self.refresh()
            self.running=False
        elif k==('ctrl','s'):
            self.save_current()
        elif k==('ctrl','o'):
            self.open_prompt()
        elif k==('ctrl','x'):
            self.switch_next()
        elif k==('alt','x'):
            self.switch_prev()
        elif k in ('up',('ctrl','p')): b.move('up',self.screenrows)
        elif k in ('down',('ctrl','n')): b.move('down',self.screenrows)
        elif k in ('right',('ctrl','f')): b.move('right',self.screenrows)
        elif k in ('left',('ctrl','b')): b.move('left',self.screenrows)
        elif k in ('home',('ctrl','a'),('alt','[D')): b.move('home',self.screenrows)
        elif k in ('end',('ctrl','e'),('alt','[C')): b.move('end',self.screenrows)
        elif k in ('pgdn',('ctrl','['),('ctrl','v')): b.move('pgdn',self.screenrows)
        elif k in ('pgup',('ctrl',']'),('alt','v')): b.move('pgup',self.screenrows)
        elif k in (('alt','f'),('ctrl','right')): b.move_word_forward()
        elif k in (('alt','b'),('ctrl','left')): b.move_word_back()
        elif k in (('alt','n'),('ctrl','down')): b.move_para_next()
        elif k in (('alt','p'),('ctrl','up')): b.move_para_prev()
        elif k==('alt','<'): b.move_top()
        elif k==('alt','>'): b.move_bottom()
        elif k in ('backspace',('ctrl','h')): b.del_back()
        elif k in ('delete',('ctrl','d')): b.del_forward()
        elif k==('ctrl','w'): b.delete_word()
        elif k==('ctrl','j'): b.delete_to_bol()
        elif k==('ctrl','k'): b.delete_to_eol()
        elif k==('ctrl','u'):
            if not b.undo_change(): self.set_message("Already at oldest change")
        elif k==('ctrl','r'):
            if not b.redo_change(): self.set_message("Already at newest change")
        elif k==('ctrl','g'):
            self.search()
        elif k==('ctrl','m') or k=='enter':
            b.insert_newline()
        elif k==('ctrl','l'):
            pass
        elif k==('ctrl','_'):
            self.show_help()
        elif isinstance(k,str) and len(k)==1 and (ord(k)>=32 and ord(k)!=127):
            b.insert_char(k)
        elif k is None:
            pass
        else:
            self.error_key(k)
    def run(self):
        self.enter_alt()
        self.enable_raw()
        try:
            self.refresh()
            while self.running:
                k=self.read_key()
                self.handle_key(k)
                if self.running:
                    self.search_query=None; self.search_current=None
                    self.refresh()
        finally:
            self.disable_raw()
            self.exit_alt()

def main():
    status=parse_args(sys.argv)
    if status[0]=='err':
        print('Error: '+status[1], file=sys.stderr)
        return 1
    if status[0]=='version':
        print(VERSION); return 0
    if status[0]=='help':
        sys.stdout.write(help_text(sys.argv[0])); return 0
    try:
        try:
            ed=Editor(status[1])
        except OSError as e:
            # Match Rust-ish display for ioctl failure.
            if getattr(e,'errno',None)==errno.ENOTTY:
                print("Error: Inappropriate ioctl for device (os error 25)", file=sys.stderr)
            else:
                print(f"Error: {e}", file=sys.stderr)
            return 1
        try:
            ed.run(); return 0
        except RuntimeError as e:
            # Some file load errors occur after entering alt screen in the original; this path is rarely used.
            print('Error: '+str(e), file=sys.stderr); return 1
    except RuntimeError as e:
        print('Error: '+str(e), file=sys.stderr); return 1

if __name__=='__main__':
    sys.exit(main())
